def t(language, key, **values):
    selected = language if language in TEXT else "pt-BR"
    return TEXT[selected][key].format(**values)


def format_money(brl_value, currency="BRL", brl_to_usd=None):
    if currency == "USD":
        if not brl_to_usd:
            return None
        return f"US$ {float(brl_value) * float(brl_to_usd):,.2f}"
    return f"R$ {float(brl_value):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
